-- Generated by scripts/generate-exercise-seed.ts from supabase/seed/exercise-catalog.json.
-- Do not edit by hand: change the JSON and run `npm run seed:catalog`.
--
-- Run as postgres after migration 0005. Safe to run again.
-- 1. Upserts the catalog by slug.
-- 2. Links user exercises (catalog_id null) whose normalized name equals a catalog name or synonym.
--    It skips names that match several catalog entries and owners who already have that entry.
--    It never merges exercises and never changes their id, so history stays intact.
-- 3. The last statement is read-only: exercises that still match the catalog, for manual review.

begin;

insert into public.exercise_catalog (slug, name_it, name_en, synonyms, equipment, primary_muscle, secondary_muscles, execution_steps, source, source_id)
values
  ('barbell-bench-press', 'Panca piana con bilanciere', 'Barbell Bench Press', array['panca piana', 'distensioni su panca piana', 'bench press', 'panca bilanciere']::text[], 'barbell', 'Petto', array['Spalle', 'Tricipiti']::text[], 'Sdraiati sulla panca con occhi sotto il bilanciere, piedi ben appoggiati e scapole addotte.
Impugna il bilanciere poco oltre la larghezza delle spalle e staccalo dai supporti.
Abbassa il bilanciere con controllo fino a sfiorare la parte centrale del petto.
Spingi verso l''alto fino a estendere i gomiti, senza staccare glutei e spalle dalla panca.', 'free-exercise-db', 'Barbell_Bench_Press_-_Medium_Grip'),
  ('incline-barbell-bench-press', 'Panca inclinata con bilanciere', 'Incline Barbell Bench Press', array['panca inclinata', 'distensioni su panca inclinata', 'incline bench press']::text[], 'barbell', 'Petto', array['Spalle', 'Tricipiti']::text[], 'Regola la panca a 30-45 gradi e sdraiati con le scapole addotte.
Impugna il bilanciere poco oltre la larghezza delle spalle e staccalo dai supporti.
Abbassa il bilanciere fino alla parte alta del petto, con i gomiti leggermente aperti.
Spingi verso l''alto fino a estendere i gomiti.', 'free-exercise-db', 'Barbell_Incline_Bench_Press_-_Medium_Grip'),
  ('dumbbell-bench-press', 'Panca piana con manubri', 'Dumbbell Bench Press', array['distensioni con manubri su panca piana', 'panca manubri', 'distensioni con manubri']::text[], 'dumbbell', 'Petto', array['Spalle', 'Tricipiti']::text[], 'Siediti sulla panca con i manubri sulle cosce, poi sdraiati portandoli all''altezza del petto.
Spingi i manubri verso l''alto fino a estendere i gomiti, con i polsi sopra i gomiti.
Abbassa i manubri con controllo fino a sentire un allungamento del petto.
Risali senza far sbattere i manubri tra loro.', 'free-exercise-db', 'Dumbbell_Bench_Press'),
  ('incline-dumbbell-press', 'Panca inclinata con manubri', 'Incline Dumbbell Press', array['distensioni con manubri su panca inclinata', 'panca inclinata manubri']::text[], 'dumbbell', 'Petto', array['Spalle', 'Tricipiti']::text[], 'Regola la panca a 30-45 gradi e porta i manubri all''altezza della parte alta del petto.
Spingi i manubri verso l''alto fino a estendere i gomiti.
Abbassa con controllo fino a sentire un allungamento del petto.
Mantieni le scapole addotte e i piedi ben appoggiati per tutta la serie.', 'free-exercise-db', 'Incline_Dumbbell_Press'),
  ('dumbbell-fly', 'Croci con manubri', 'Dumbbell Flyes', array['croci', 'croci su panca piana', 'croci manubri', 'aperture con manubri']::text[], 'dumbbell', 'Petto', array['Spalle']::text[], 'Sdraiati sulla panca con i manubri sopra il petto, palmi uno di fronte all''altro.
Con i gomiti leggermente flessi, apri le braccia ad arco fino a sentire l''allungamento del petto.
Riporta i manubri sopra il petto stringendo i pettorali.
Usa un carico moderato: il movimento è di isolamento.', 'free-exercise-db', 'Dumbbell_Flyes'),
  ('cable-crossover', 'Croci ai cavi', 'Cable Crossover', array['croci al cavo', 'croci ai cavi alti', 'cable crossover', 'croci cavi']::text[], 'other', 'Petto', array['Spalle']::text[], 'Posizionati al centro dei due cavi alti, un passo avanti, con il busto leggermente inclinato.
Con i gomiti leggermente flessi, porta le mani davanti al petto in un movimento ad arco.
Stringi i pettorali per un istante quando le mani si incontrano.
Torna lentamente alla posizione iniziale, controllando il carico.', 'free-exercise-db', 'Cable_Crossover'),
  ('chest-press-machine', 'Chest press', 'Machine Chest Press', array['chest press alla macchina', 'pressa per il petto', 'macchina per il petto', 'pectoral machine']::text[], 'other', 'Petto', array['Spalle', 'Tricipiti']::text[], 'Regola il sedile in modo che le impugnature siano all''altezza del petto.
Schiena appoggiata allo schienale, spingi in avanti fino a estendere i gomiti.
Torna indietro con controllo, senza far toccare i pesi tra una ripetizione e l''altra.', 'free-exercise-db', 'Leverage_Chest_Press'),
  ('push-up', 'Piegamenti sulle braccia', 'Push-Up', array['flessioni', 'piegamenti', 'push-up', 'flessioni a terra']::text[], 'other', 'Petto', array['Spalle', 'Tricipiti']::text[], 'Appoggia le mani a terra poco oltre la larghezza delle spalle, con il corpo in linea retta.
Abbassa il petto verso il pavimento flettendo i gomiti.
Spingi verso l''alto fino a estendere le braccia, tenendo addome e glutei contratti.', 'free-exercise-db', 'Pushups'),
  ('chest-dip', 'Dip alle parallele', 'Chest Dip', array['dip', 'dips', 'parallele', 'distensioni alle parallele']::text[], 'other', 'Petto', array['Tricipiti', 'Spalle']::text[], 'Sostieniti sulle parallele a braccia tese, con il busto inclinato in avanti.
Scendi flettendo i gomiti fino a sentire un buon allungamento del petto.
Spingi verso l''alto fino a estendere le braccia.', 'free-exercise-db', 'Dips_-_Chest_Version'),
  ('barbell-deadlift', 'Stacco da terra', 'Barbell Deadlift', array['stacco', 'stacco con bilanciere', 'stacco da terra con bilanciere', 'deadlift']::text[], 'barbell', 'Lombari', array['Glutei', 'Femorali', 'Quadricipiti', 'Trapezi', 'Avambracci']::text[], 'Posizionati con il bilanciere sopra la metà dei piedi e piedi alla larghezza del bacino.
Piegati ad afferrare il bilanciere, con schiena neutra, petto alto e braccia tese.
Spingi sui piedi ed estendi gambe e bacino insieme, tenendo il bilanciere vicino al corpo.
Arrivato in piedi, non iperestendere la schiena. Riscendi con controllo lungo le gambe.', 'free-exercise-db', 'Barbell_Deadlift'),
  ('barbell-row', 'Rematore con bilanciere', 'Bent Over Barbell Row', array['rematore', 'rematore bilanciere', 'rematore a busto flesso', 'barbell row']::text[], 'barbell', 'Dorso', array['Dorsali', 'Bicipiti', 'Spalle']::text[], 'Impugna il bilanciere e inclina il busto in avanti, con schiena neutra e ginocchia leggermente flesse.
Tira il bilanciere verso l''addome portando i gomiti indietro.
Stringi le scapole per un istante in alto.
Abbassa con controllo fino a braccia tese, senza muovere il busto.', 'free-exercise-db', 'Bent_Over_Barbell_Row'),
  ('one-arm-dumbbell-row', 'Rematore con manubrio a un braccio', 'One-Arm Dumbbell Row', array['rematore con manubrio', 'rematore manubrio', 'rematore a un braccio', 'dumbbell row']::text[], 'dumbbell', 'Dorso', array['Dorsali', 'Bicipiti', 'Spalle']::text[], 'Appoggia una mano e un ginocchio sulla panca, con la schiena parallela al suolo.
Con l''altra mano tieni il manubrio a braccio disteso.
Tira il manubrio verso il fianco portando il gomito indietro e in alto.
Abbassa con controllo, poi ripeti e cambia lato.', 'free-exercise-db', 'One-Arm_Dumbbell_Row'),
  ('pull-up', 'Trazioni alla sbarra', 'Pull-Up', array['trazioni', 'trazioni presa prona', 'pull-up', 'pullup']::text[], 'other', 'Dorsali', array['Bicipiti', 'Dorso']::text[], 'Impugna la sbarra a presa prona, poco oltre la larghezza delle spalle, e sospenditi a braccia tese.
Tira il corpo verso l''alto portando i gomiti verso i fianchi, fino a superare la sbarra con il mento.
Scendi con controllo fino a braccia tese, senza dondolare.', 'free-exercise-db', 'Pullups'),
  ('chin-up', 'Trazioni a presa supina', 'Chin-Up', array['trazioni supine', 'chin-up', 'chin up', 'trazioni presa inversa']::text[], 'other', 'Dorsali', array['Bicipiti', 'Avambracci', 'Dorso']::text[], 'Impugna la sbarra a presa supina, alla larghezza delle spalle, e sospenditi a braccia tese.
Tira il corpo verso l''alto fino a portare il mento sopra la sbarra.
Scendi con controllo fino a braccia tese.', 'free-exercise-db', 'Chin-Up'),
  ('lat-pulldown', 'Lat machine', 'Wide-Grip Lat Pulldown', array['lat machine presa larga', 'pulldown', 'lat pulldown', 'trazioni al cavo alto']::text[], 'other', 'Dorsali', array['Bicipiti', 'Dorso', 'Spalle']::text[], 'Siediti bloccando le cosce sotto i cuscinetti e impugna la barra a presa larga.
Inclina leggermente il busto indietro e tira la barra fino all''altezza della parte alta del petto.
Porta i gomiti verso il basso e stringi le scapole.
Risali con controllo fino a braccia tese.', 'free-exercise-db', 'Wide-Grip_Lat_Pulldown'),
  ('seated-cable-row', 'Pulley basso', 'Seated Cable Row', array['pulley', 'rematore ai cavi', 'rematore seduto al cavo', 'low row', 'rowing seduto']::text[], 'other', 'Dorso', array['Dorsali', 'Bicipiti', 'Spalle']::text[], 'Siediti con i piedi sulle pedane, ginocchia leggermente flesse e schiena dritta.
Tira la maniglia verso l''addome portando i gomiti indietro.
Stringi le scapole per un istante, senza dondolare con il busto.
Torna lentamente alla posizione iniziale.', 'free-exercise-db', 'Seated_Cable_Rows'),
  ('t-bar-row', 'Rematore con T-bar', 'T-Bar Row', array['t-bar', 'rematore t-bar', 'rematore al t-bar']::text[], 'barbell', 'Dorso', array['Dorsali', 'Bicipiti']::text[], 'Posizionati sopra la barra con il busto inclinato e la schiena neutra.
Impugna la maniglia e tira il carico verso il petto portando i gomiti indietro.
Stringi le scapole in alto, poi abbassa con controllo.', 'free-exercise-db', 'T-Bar_Row_with_Handle'),
  ('face-pull', 'Face pull', 'Face Pull', array['tirate al viso', 'tirate al viso ai cavi', 'face pull ai cavi']::text[], 'other', 'Spalle', array['Dorso', 'Trapezi']::text[], 'Imposta il cavo con la corda all''altezza del viso e afferrala a presa neutra.
Fai un passo indietro e tira la corda verso il viso, aprendo i gomiti verso l''esterno.
Stringi le scapole per un istante, poi torna con controllo.', 'free-exercise-db', 'Face_Pull'),
  ('back-extension', 'Estensioni per la schiena', 'Back Extension', array['iperestensioni', 'estensioni lombari', 'panca per lombari', 'hyperextension']::text[], 'other', 'Lombari', array['Glutei', 'Femorali']::text[], 'Posizionati sulla panca con i fianchi appena sopra il cuscino e le caviglie bloccate.
Incrocia le braccia sul petto e abbassa il busto con la schiena neutra.
Risali contraendo glutei e lombari fino ad allineare il corpo, senza iperestendere.', 'free-exercise-db', 'Hyperextensions_Back_Extensions'),
  ('straight-arm-pulldown', 'Pulldown a braccia tese', 'Straight-Arm Pulldown', array['pullover ai cavi', 'pulldown braccia tese', 'pushdown per dorsali']::text[], 'other', 'Dorsali', array[]::text[], 'In piedi davanti al cavo alto, impugna la barra a braccia tese e busto leggermente inclinato.
Porta la barra verso le cosce con le braccia quasi tese, contraendo i dorsali.
Risali lentamente fino all''altezza della testa.', 'free-exercise-db', 'Straight-Arm_Pulldown'),
  ('barbell-shrug', 'Scrollate con bilanciere', 'Barbell Shrug', array['scrollate', 'scrollate di spalle', 'shrug', 'scrollate bilanciere']::text[], 'barbell', 'Trapezi', array[]::text[], 'In piedi, impugna il bilanciere davanti alle cosce a braccia tese.
Solleva le spalle verso le orecchie senza piegare i gomiti.
Resta un istante in alto, poi abbassa con controllo.', 'free-exercise-db', 'Barbell_Shrug'),
  ('standing-barbell-overhead-press', 'Military press', 'Standing Military Press', array['lento avanti con bilanciere', 'overhead press', 'distensioni sopra la testa', 'shoulder press con bilanciere']::text[], 'barbell', 'Spalle', array['Tricipiti']::text[], 'In piedi, impugna il bilanciere poco oltre la larghezza delle spalle e appoggialo sulla parte alta del petto.
Contrai addome e glutei, poi spingi il bilanciere sopra la testa fino a estendere i gomiti.
Porta la testa leggermente avanti quando il bilanciere la supera.
Abbassa con controllo fino alla posizione iniziale.', 'free-exercise-db', 'Standing_Military_Press'),
  ('dumbbell-shoulder-press', 'Lento avanti con manubri', 'Dumbbell Shoulder Press', array['shoulder press', 'shoulder press con manubri', 'distensioni con manubri sopra la testa', 'lento manubri']::text[], 'dumbbell', 'Spalle', array['Tricipiti']::text[], 'Siediti con la schiena appoggiata e porta i manubri all''altezza delle spalle.
Spingi i manubri verso l''alto fino a estendere i gomiti.
Abbassa con controllo fino a portare i gomiti poco sotto l''altezza delle spalle.', 'free-exercise-db', 'Dumbbell_Shoulder_Press'),
  ('arnold-press', 'Arnold press', 'Arnold Dumbbell Press', array['distensioni arnold', 'arnold dumbbell press']::text[], 'dumbbell', 'Spalle', array['Tricipiti']::text[], 'Parti con i manubri davanti al petto, palmi rivolti verso di te.
Spingi verso l''alto ruotando i polsi, fino ad arrivare a palmi in avanti con i gomiti estesi.
Scendi invertendo la rotazione fino alla posizione iniziale.', 'free-exercise-db', 'Arnold_Dumbbell_Press'),
  ('dumbbell-lateral-raise', 'Alzate laterali con manubri', 'Side Lateral Raise', array['alzate laterali', 'alzate laterali manubri', 'lateral raise', 'alzate laterali per spalle']::text[], 'dumbbell', 'Spalle', array[]::text[], 'In piedi, con un manubrio per mano lungo i fianchi e i gomiti leggermente flessi.
Solleva le braccia di lato fino all''altezza delle spalle.
Abbassa lentamente, senza dondolare con il busto.', 'free-exercise-db', 'Side_Lateral_Raise'),
  ('dumbbell-front-raise', 'Alzate frontali con manubri', 'Front Dumbbell Raise', array['alzate frontali', 'alzate frontali manubri', 'front raise']::text[], 'dumbbell', 'Spalle', array[]::text[], 'In piedi, con un manubrio per mano davanti alle cosce.
Solleva un braccio davanti a te, quasi teso, fino all''altezza delle spalle.
Abbassa con controllo e alterna le braccia.', 'free-exercise-db', 'Front_Dumbbell_Raise'),
  ('rear-delt-fly', 'Alzate posteriori con manubri', 'Rear Delt Fly', array['alzate a 90', 'alzate busto flesso', 'croci inverse', 'deltoidi posteriori', 'rear delt fly']::text[], 'dumbbell', 'Spalle', array['Dorso']::text[], 'Inclina il busto in avanti con la schiena neutra e i manubri sotto le spalle.
Con i gomiti leggermente flessi, apri le braccia di lato fino all''altezza del busto.
Abbassa lentamente, senza darti slancio.', 'free-exercise-db', 'Reverse_Flyes'),
  ('upright-row', 'Tirate al mento con bilanciere', 'Upright Barbell Row', array['tirate al mento', 'upright row', 'rematore verticale']::text[], 'barbell', 'Spalle', array['Trapezi']::text[], 'In piedi, impugna il bilanciere a presa prona, poco più stretta delle spalle.
Tira il bilanciere verso il petto, portando i gomiti in alto e verso l''esterno.
Fermati all''altezza del petto, poi abbassa con controllo.', 'free-exercise-db', 'Upright_Barbell_Row'),
  ('barbell-back-squat', 'Squat con bilanciere', 'Barbell Back Squat', array['squat', 'squat bilanciere', 'back squat', 'accosciata']::text[], 'barbell', 'Quadricipiti', array['Glutei', 'Femorali', 'Lombari']::text[], 'Appoggia il bilanciere sui trapezi, piedi poco più larghi delle spalle e punte leggermente aperte.
Scendi flettendo anche e ginocchia insieme, con schiena neutra e petto alto.
Scendi almeno fino a cosce parallele al suolo, con i ginocchi in linea con i piedi.
Spingi sui piedi per risalire, estendendo gambe e bacino.', 'free-exercise-db', 'Barbell_Squat'),
  ('front-squat', 'Front squat', 'Front Barbell Squat', array['squat frontale', 'squat anteriore', 'front squat con bilanciere']::text[], 'barbell', 'Quadricipiti', array['Glutei', 'Femorali']::text[], 'Appoggia il bilanciere sulle spalle davanti, con i gomiti alti e le dita sotto la barra.
Scendi mantenendo il busto verticale e i gomiti alti.
Scendi fino a cosce almeno parallele al suolo, poi spingi sui piedi per risalire.', 'free-exercise-db', 'Front_Barbell_Squat'),
  ('leg-press', 'Leg press', 'Leg Press', array['pressa', 'pressa orizzontale', 'pressa 45', 'pressa per gambe']::text[], 'other', 'Quadricipiti', array['Glutei', 'Femorali', 'Polpacci']::text[], 'Siediti con la schiena e il bacino ben appoggiati, piedi sulla pedana alla larghezza delle spalle.
Sblocca il carico e scendi flettendo le ginocchia, senza staccare il bacino dallo schienale.
Spingi sulla pedana fino a quasi estendere le gambe, senza bloccare le ginocchia.', 'free-exercise-db', 'Leg_Press'),
  ('romanian-deadlift', 'Stacco rumeno', 'Romanian Deadlift', array['rdl', 'stacco a gambe semitese', 'stacco rumeno con bilanciere']::text[], 'barbell', 'Femorali', array['Glutei', 'Lombari']::text[], 'In piedi con il bilanciere davanti alle cosce, ginocchia appena flesse.
Spingi il bacino indietro e abbassa il bilanciere lungo le gambe, con la schiena neutra.
Scendi fino a sentire l''allungamento dei femorali, poi risali spingendo il bacino in avanti.', 'free-exercise-db', 'Romanian_Deadlift'),
  ('sumo-deadlift', 'Stacco sumo', 'Sumo Deadlift', array['stacco sumo con bilanciere', 'sumo deadlift']::text[], 'barbell', 'Glutei', array['Femorali', 'Quadricipiti', 'Adduttori', 'Lombari']::text[], 'Posizionati con i piedi molto larghi e le punte aperte, il bilanciere sopra la metà dei piedi.
Piegati e impugna il bilanciere all''interno delle gambe, con schiena neutra e petto alto.
Spingi sui piedi aprendo le ginocchia ed estendi gambe e bacino fino a stare in piedi.
Riscendi con controllo lungo le gambe.', 'free-exercise-db', 'Sumo_Deadlift'),
  ('barbell-lunge', 'Affondi con bilanciere', 'Barbell Lunge', array['affondi bilanciere', 'affondi con il bilanciere']::text[], 'barbell', 'Quadricipiti', array['Glutei', 'Femorali']::text[], 'Appoggia il bilanciere sui trapezi e fai un passo in avanti.
Scendi flettendo entrambe le ginocchia fino a sfiorare il suolo con il ginocchio posteriore.
Spingi con la gamba anteriore per tornare alla posizione iniziale, poi ripeti dall''altro lato.', 'free-exercise-db', 'Barbell_Lunge'),
  ('dumbbell-lunge', 'Affondi con manubri', 'Dumbbell Lunges', array['affondi', 'affondi manubri', 'affondi camminati', 'walking lunge']::text[], 'dumbbell', 'Quadricipiti', array['Glutei', 'Femorali']::text[], 'In piedi con un manubrio per mano lungo i fianchi, fai un passo in avanti.
Scendi flettendo entrambe le ginocchia fino a sfiorare il suolo con il ginocchio posteriore.
Spingi con la gamba anteriore per tornare in piedi, poi alterna le gambe.', 'free-exercise-db', 'Dumbbell_Lunges'),
  ('bulgarian-split-squat', 'Squat bulgaro', 'Bulgarian Split Squat', array['affondi bulgari', 'split squat bulgaro', 'squat bulgaro con manubri', 'bulgarian split squat']::text[], 'dumbbell', 'Quadricipiti', array['Glutei', 'Femorali']::text[], 'Appoggia il collo del piede posteriore su una panca dietro di te, con un manubrio per mano.
Scendi flettendo il ginocchio anteriore, con il busto eretto.
Spingi sul piede anteriore per risalire. Completa le ripetizioni, poi cambia gamba.', 'free-exercise-db', 'Split_Squat_with_Dumbbells'),
  ('leg-extension', 'Leg extension', 'Leg Extensions', array['estensioni per quadricipiti', 'estensioni delle gambe', 'leg extension alla macchina']::text[], 'other', 'Quadricipiti', array[]::text[], 'Siediti alla macchina con la schiena appoggiata e il cuscinetto sopra le caviglie.
Estendi le gambe fino quasi a distenderle, contraendo i quadricipiti.
Torna indietro lentamente, controllando il carico.', 'free-exercise-db', 'Leg_Extensions'),
  ('lying-leg-curl', 'Leg curl da sdraiato', 'Lying Leg Curls', array['leg curl', 'curl femorali', 'leg curl sdraiato', 'femorali alla macchina']::text[], 'other', 'Femorali', array[]::text[], 'Sdraiati a pancia in giù sulla macchina, con il cuscinetto appena sopra i talloni.
Fletti le ginocchia portando i talloni verso i glutei.
Torna lentamente alla posizione iniziale, senza sollevare il bacino.', 'free-exercise-db', 'Lying_Leg_Curls'),
  ('seated-leg-curl', 'Leg curl da seduto', 'Seated Leg Curl', array['leg curl seduto', 'curl femorali da seduto']::text[], 'other', 'Femorali', array[]::text[], 'Siediti alla macchina con la schiena appoggiata e il cuscinetto sopra le caviglie.
Fletti le ginocchia portando i talloni verso il basso e indietro.
Torna lentamente alla posizione iniziale, controllando il carico.', 'free-exercise-db', 'Seated_Leg_Curl'),
  ('standing-calf-raise', 'Calf raise in piedi', 'Standing Calf Raises', array['calf raise', 'polpacci in piedi', 'calf in piedi', 'sollevamenti sulle punte']::text[], 'other', 'Polpacci', array[]::text[], 'Posiziona le spalle sotto i cuscinetti e le punte dei piedi sul bordo della pedana.
Solleva i talloni il più in alto possibile, contraendo i polpacci.
Abbassa i talloni sotto il livello della pedana per allungare bene il muscolo.', 'free-exercise-db', 'Standing_Calf_Raises'),
  ('seated-calf-raise', 'Calf raise da seduto', 'Seated Calf Raise', array['polpacci da seduto', 'calf da seduto', 'calf seduto']::text[], 'other', 'Polpacci', array[]::text[], 'Siediti alla macchina con i cuscinetti sopra le ginocchia e le punte dei piedi sulla pedana.
Solleva i talloni il più in alto possibile.
Abbassa lentamente fino a sentire l''allungamento dei polpacci.', 'free-exercise-db', 'Seated_Calf_Raise'),
  ('barbell-hip-thrust', 'Hip thrust', 'Barbell Hip Thrust', array['spinta d''anca', 'ponte glutei con bilanciere', 'hip thrust con bilanciere']::text[], 'barbell', 'Glutei', array['Femorali', 'Quadricipiti']::text[], 'Appoggia la parte alta della schiena su una panca, con il bilanciere sopra i fianchi.
Piedi a terra, ginocchia flesse: spingi il bacino verso l''alto contraendo i glutei.
In alto, il busto e le cosce formano una linea retta. Scendi con controllo.', 'free-exercise-db', 'Barbell_Hip_Thrust'),
  ('dumbbell-step-up', 'Step-up con manubri', 'Dumbbell Step Ups', array['step up', 'step-up', 'salite sulla panca', 'salite sullo step']::text[], 'dumbbell', 'Quadricipiti', array['Glutei', 'Femorali']::text[], 'Davanti a una panca o a uno step, con un manubrio per mano.
