  ('barbell-curl', 'Curl con bilanciere', 'Barbell Curl', array['curl', 'curl bilanciere', 'curl in piedi con bilanciere', 'curl per bicipiti']::text[], 'barbell', 'Bicipiti', array['Avambracci']::text[], 'In piedi, impugna il bilanciere a presa supina alla larghezza delle spalle.
