  ('crunch', 'Crunch', 'Crunches', array['crunch addominali', 'addominali', 'addominali a terra']::text[], 'other', 'Addominali', array[]::text[], 'Sdraiati sulla schiena con le ginocchia flesse e i piedi a terra.
Con le mani ai lati della testa, solleva spalle e parte alta della schiena contraendo l''addome.
Abbassa lentamente senza tirare il collo.', 'free-exercise-db', 'Crunches'),
  ('hanging-leg-raise', 'Sollevamento gambe alla sbarra', 'Hanging Leg Raise', array['leg raise alla sbarra', 'sollevamento gambe', 'leg raise sospeso', 'hanging leg raise']::text[], 'other', 'Addominali', array[]::text[], 'Sospenditi alla sbarra a braccia tese, senza dondolare.
Solleva le gambe davanti a te, fino ad arrivare almeno all''orizzontale, contraendo l''addome.
Abbassa con controllo senza darti slancio.', 'free-exercise-db', 'Hanging_Leg_Raise'),
  ('cable-crunch', 'Crunch ai cavi', 'Cable Crunch', array['crunch al cavo', 'crunch cavo alto', 'addominali ai cavi']::text[], 'other', 'Addominali', array[]::text[], 'Inginocchiati davanti al cavo alto e tieni la corda ai lati della testa.
Fletti il busto portando i gomiti verso le cosce, contraendo l''addome.
Risali lentamente, senza spingere con i fianchi.', 'free-exercise-db', 'Cable_Crunch'),
  ('russian-twist', 'Russian twist', 'Russian Twist', array['torsioni russe', 'rotazioni del busto da seduto']::text[], 'other', 'Addominali', array['Lombari']::text[], 'Siediti a terra con il busto inclinato indietro e i piedi appoggiati o sollevati.
Ruota il busto da un lato all''altro, portando le mani accanto ai fianchi.
Mantieni la schiena dritta e il ritmo controllato.', 'free-exercise-db', 'Russian_Twist'),
  ('ab-wheel-rollout', 'Ruota addominale', 'Ab Wheel Rollout', array['ab wheel', 'rollout', 'ab roller', 'rullo per addominali']::text[], 'other', 'Addominali', array['Spalle']::text[], 'Inginocchiati e impugna la ruota con le braccia tese sotto le spalle.
Fai rotolare la ruota in avanti, mantenendo addome contratto e schiena neutra.
Quando senti di non poter controllare la schiena, torna indietro contraendo l''addome.', 'free-exercise-db', 'Ab_Roller'),
  ('farmers-walk', 'Farmer''s walk', 'Farmer''s Walk', array['farmer walk', 'camminata del contadino', 'passeggiata del contadino', 'farmer''s carry']::text[], 'other', 'Avambracci', array['Trapezi', 'Addominali', 'Glutei']::text[], 'Solleva da terra un peso per mano e stai in piedi con le spalle indietro e giù.
Cammina a passi corti e controllati per la distanza prevista.
Mantieni il busto eretto, senza inclinarti da un lato.', 'free-exercise-db', 'Farmers_Walk')
on conflict (slug) do update set
  name_it = excluded.name_it,
  name_en = excluded.name_en,
  synonyms = excluded.synonyms,
  equipment = excluded.equipment,
  primary_muscle = excluded.primary_muscle,
  secondary_muscles = excluded.secondary_muscles,
  execution_steps = excluded.execution_steps,
  source = excluded.source,
  source_id = excluded.source_id;

with catalog_names as (
  select c.id as catalog_id, trim(lower(translate(n.name, 'àáâäèéêëìíîïòóôöùúûüç', 'aaaaeeeeiiiioooouuuuc'))) as name_key
  from public.exercise_catalog c
  cross join lateral unnest(c.synonyms || c.name_it) as n(name)
),
matches as (
  select distinct e.id as exercise_id, e.owner_id, e.archived, cn.catalog_id
  from public.exercise e
  join catalog_names cn on cn.name_key = trim(lower(translate(e.name, 'àáâäèéêëìíîïòóôöùúûüç', 'aaaaeeeeiiiioooouuuuc')))
  where e.catalog_id is null
),
single_match as (
  select m.*, count(*) over (partition by m.exercise_id) as catalog_count
  from matches m
),
ranked as (
  select s.*, row_number() over (partition by s.owner_id, s.catalog_id order by s.archived, s.exercise_id) as rank_in_owner
  from single_match s
  where s.catalog_count = 1
)
update public.exercise e
set catalog_id = r.catalog_id
from ranked r
where e.id = r.exercise_id
  and r.rank_in_owner = 1
  and not exists (
    select 1 from public.exercise o where o.owner_id = e.owner_id and o.catalog_id = r.catalog_id
  );

commit;

with catalog_names as (
  select c.id as catalog_id, trim(lower(translate(n.name, 'àáâäèéêëìíîïòóôöùúûüç', 'aaaaeeeeiiiioooouuuuc'))) as name_key
  from public.exercise_catalog c
  cross join lateral unnest(c.synonyms || c.name_it) as n(name)
)
select e.owner_id,
       e.id as exercise_id,
       e.name as exercise_name,
       string_agg(distinct c.slug, ', ') as catalog_slugs,
       string_agg(distinct o.name, ', ') as already_linked_as
from public.exercise e
join catalog_names cn on cn.name_key = trim(lower(translate(e.name, 'àáâäèéêëìíîïòóôöùúûüç', 'aaaaeeeeiiiioooouuuuc')))
join public.exercise_catalog c on c.id = cn.catalog_id
left join public.exercise o on o.owner_id = e.owner_id and o.catalog_id = c.id
where e.catalog_id is null
group by e.owner_id, e.id, e.name
order by e.owner_id, e.name;
